/* Luma. A device-local product prototype. All initial financial records are fictional.
   Values are stored as integer cents. No bank or payment service is connected. */
(()=>{'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const I=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`,icons=()=>window.lucide?.createIcons({attrs:{'stroke-width':1.7}}),goAttr=(s,e='')=>`data-go="${s}" ${e}`,act=(s,e='')=>`data-action="${s}" ${e}`;
const money=(c,d=2)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:d,maximumFractionDigits:d}).format(c/100),plain=c=>(c/100).toFixed(2);
const CAT=[{id:'food',name:'Food & drink',icon:'utensils',color:'#b7f12b'},{id:'shopping',name:'Shopping',icon:'shopping-bag',color:'#8ebc44'},{id:'transport',name:'Transport',icon:'train-front',color:'#60844e'},{id:'home',name:'Home & bills',icon:'house',color:'#d7e8b4'},{id:'subscriptions',name:'Subscriptions',icon:'repeat-2',color:'#78975a'},{id:'other',name:'Other',icon:'shapes',color:'#445e37'}];
const cat=id=>CAT.find(x=>x.id===id)||CAT[5];
const seedTransactions=[['Rent','home',95000,1],['Netflix','subscriptions',1549,3],['Whole Foods','food',6280,4],['Morning coffee','food',1420,5],['City transit','transport',3500,5],['Spotify','subscriptions',1099,6],['Trader Joe’s','food',7810,7],['Uniqlo','shopping',12900,8],['Electricity','home',10539,9],['Neighborhood dinner','food',4850,10],['Adobe','subscriptions',2299,11],['Corner market','food',5265,12],['Uber','transport',2450,13],['iCloud+','subscriptions',299,14],['Morning coffee','food',960,15],['Notion','subscriptions',1000,15],['Friends & noodles','food',7240,16],['Nike','shopping',8900,18],['Whole Foods','food',8990,19],['Fitness class','other',7000,20],['Lunch at Fern','food',5630,21],['City transit','transport',2800,22],['Sunday groceries','food',8410,23],['Coffee & a catch-up','food',1640,24],['Trader Joe’s','food',5850,26]].map(([merchant,category,cents,day],i)=>({id:'t'+i,merchant,category,cents,date:`2026-09-${String(day).padStart(2,'0')}`,note:'',payment:'Debit card',created:i}));
const previous=seedTransactions.filter((_,i)=>i%4!==0).map((t,i)=>({...t,id:'a'+i,date:t.date.replace('2026-09','2026-08'),cents:Math.round(t.cents*.88)}));
const seedSubs=[['Netflix',1549,'2026-10-03','netflix','N'],['Spotify',1099,'2026-10-06','spotify','S'],['Adobe',2299,'2026-10-11','adobe','A'],['iCloud+',299,'2026-10-14','icloud','cloud'],['Notion',1000,'2026-10-15','notion','N']].map(([name,cents,next,brand,mark],i)=>({id:'s'+i,name,cents,next,brand,mark,cycle:'monthly',status:'active',remind:true}));
const defaults={budget:{food:50000,shopping:30000,transport:20000,home:100000,subscriptions:15000,other:25000},transactions:[...seedTransactions,...previous],subscriptions:seedSubs,preferences:{overspend:true,renewals:true,weekly:false,hideAmounts:false,reduced:false}};
let saved;try{saved=JSON.parse(localStorage.getItem('luma-expenses-v1')||'null')}catch{}
const data=saved&&Array.isArray(saved.transactions)&&saved.budget&&saved.subscriptions?saved:structuredClone(defaults);
const state={mode:'presentation',screen:'welcome',month:'2026-09',tx:'t24',category:'food',sub:'s0',query:'',filter:'all',subFilter:'active',calendarMonth:'2026-10',calendarDay:3,alertTab:'Updates',insightTab:'Spending',formCategory:'food',error:'',dialog:null,toast:'',width:390,hotspots:false,reportState:'actual'};
const screens=[
 ['welcome','Welcome','Money, without the mystery.','A minimal introduction carries the reference’s luminous lime surface, overlapping circles, and light numerical typography.',['Tap Find your balance to begin.','Open How Luma works for a short walkthrough.']],
 ['overview','Monthly overview','Know where you stand.','A live balance, spending pace, and recent activity bring the month into focus.',['Add an expense and watch every total update.','Tap the balance toggle to hide amounts.','Open the warning to review your budget.']],
 ['transactions','Transactions','A month in the details.','An open transaction list groups purchases by date, with category filters and month navigation.',['Filter food, shopping, or subscriptions.','Switch between September and August.','Open any transaction for its details.']],
 ['expense','Expense detail','Every purchase has a place.','Clear amounts and compact metadata make a transaction easy to review, recategorize, or remove.',['Change its category.','Delete the transaction from the demo.','Return to the updated activity list.']],
 ['add','Add an expense','A quick, considered entry.','A large amount field and direct category choices make logging a purchase feel effortless.',['Enter an amount, merchant, category, and date.','Try saving an incomplete entry to see validation.','Save to update spending, budgets, and insights.']],
 ['budgets','Monthly budgets','A little structure goes a long way.','Category budgets show the amount spent, room remaining, and clear over-budget states.',['Open a category for its spending breakdown.','Edit monthly category limits.','Compare actual spending with the overall budget.']],
 ['category','Category detail','Understand the overrun.','A category view connects its budget to the purchases that shaped it.',['Review the Food & drink overrun.','Open a transaction.','Adjust the category budget.']],
 ['budget-edit','Set your budget','Make room for what matters.','Category limits roll into one monthly budget, with a live preview before saving.',['Change a category’s monthly limit.','Watch the total update.','Save and review the new budget status.']],
 ['insights','Spending insights','See the pattern behind the purchases.','Cumulative spending and category shares reveal how the month is developing.',['Switch between spending pace and categories.','Compare actual spend with a budget pace.','Use the monthly report for a compact summary.']],
 ['subscriptions','Subscriptions','The small things add up.','Active commitments, monthly equivalents, and upcoming charges are gathered in one view.',['View active, paused, and cancelled subscriptions.','Add a recurring payment.','Open a subscription to manage tracking.']],
 ['subscription','Subscription detail','A clearer recurring commitment.','Price, cadence, renewal date, and reminder controls make recurring spending visible.',['Pause or resume tracking.','Turn renewal reminders on or off.','Mark a subscription cancelled in the local demo.']],
 ['subscription-add','Add a subscription','No more invisible renewals.','Capture a service, its price, its billing cycle, and its next renewal date.',['Add a monthly or annual service.','Watch its monthly equivalent update.','Find its next charge on the renewal calendar.']],
 ['calendar','Renewal calendar','Know what is coming.','A calendar marks renewal days and reveals the charges expected on each date.',['Select a marked date.','Move between months.','Open a service from the day’s charge list.']],
 ['alerts','Budget alerts','A useful heads-up.','Overspending and renewal reminders are separate from delivery preferences.',['Review the forecast overrun and category warnings.','Open the relevant budget.','Toggle budget, renewal, and weekly reminders.']],
 ['search','Search expenses','Find a purchase in a moment.','Search merchant names, categories, and notes, with contextual results and a useful empty state.',['Search “coffee”, “home”, or “Netflix”.','Try a term without matches.','Open a result to inspect it.']],
 ['settings','Settings','Your money. Your preferences.','Simple grouped settings cover privacy, notifications, budget setup, and local demo data.',['Change alert preferences.','Hide balances or reduce motion.','Reset the sample data when you need a fresh walkthrough.']],
 ['summary','Monthly summary','The month, in perspective.','One report connects total spending, remaining budget, category totals, and recurring commitments.',['Switch months to inspect another period.','Review the largest spending category.','Return to the budget to adjust your plan.']]
];
const persist=()=>{try{localStorage.setItem('luma-expenses-v1',JSON.stringify(data))}catch{}};
const list=()=>data.transactions.filter(t=>t.date.startsWith(state.month)).sort((a,b)=>b.date.localeCompare(a.date)||b.created-a.created);
const total=()=>list().reduce((s,t)=>s+t.cents,0),budget=()=>Object.values(data.budget).reduce((s,v)=>s+Number(v),0),byCategory=id=>list().filter(t=>t.category===id).reduce((s,t)=>s+t.cents,0);
const daysIn=m=>new Date(Number(m.slice(0,4)),Number(m.slice(5)),0).getDate(),elapsed=()=>state.month==='2026-09'?26:daysIn(state.month),forecast=()=>Math.round(total()/elapsed()*daysIn(state.month));
const activeSubs=()=>data.subscriptions.filter(s=>s.status==='active'),monthlySubs=()=>Math.round(activeSubs().reduce((sum,s)=>sum+(s.cycle==='annual'?s.cents/12:s.cents),0)),annualSubs=()=>activeSubs().reduce((sum,s)=>sum+(s.cycle==='annual'?s.cents:s.cents*12),0);
const dateLabel=(date,options={month:'short',day:'numeric'})=>new Date(date+'T12:00:00').toLocaleDateString('en-US',options),monthName=m=>dateLabel(m+'-01',{month:'long',year:'numeric'});
const currentTx=()=>data.transactions.find(t=>t.id===state.tx)||list()[0]||data.transactions[0],currentSub=()=>data.subscriptions.find(s=>s.id===state.sub)||data.subscriptions[0];
const pbtn=(s,a='',cls='')=>`<button class="primary ${cls}" ${a}>${s}</button>`,link=(s,a='',sym='arrow-up-right')=>`<button class="tertiary" ${a}>${esc(s)}${sym?I(sym):''}</button>`,ib=(sym,label,a='',cls='')=>`<button class="icon-button ${cls}" aria-label="${esc(label)}" ${a}>${I(sym)}</button>`;
const top=(title='',back='overview',right='')=>`<div class="top-bar">${ib('chevron-left','Go back',goAttr(back),'transparent')}<strong>${esc(title)}</strong>${right||'<span style="width:44px"></span>'}</div>`;
const section=(s,l='',to='')=>`<div class="section-heading"><h2>${s}</h2>${l?link(l,goAttr(to),'chevron-right'):''}</div>`,chip=(s,on=false,a='')=>`<button class="chip ${on?'selected':''}" aria-pressed="${on}" ${a}>${esc(s)}</button>`;
const sc=(body,cls='')=>`<div class="phone-scroll ${cls}">${body}</div>`,badge=(s,cls='')=>`<span class="pill-badge ${cls}">${s}</span>`;
function nav(active){return `<nav class="bottom-nav" aria-label="App navigation">${[['overview','layout-dashboard','Overview'],['transactions','arrow-left-right','Activity'],['budgets','chart-no-axes-combined','Budget'],['subscriptions','repeat-2','Recurring']].map(([id,sym,name])=>`<button ${goAttr(id)} class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${I(sym)}<span>${name}</span></button>`).join('')}</nav>`}
const status=()=>`<div class="status-bar"><span>9:41</span><div class="island"></div><div class="status-icons">${I('signal')}${I('wifi')}${I('battery-full')}</div></div>`;
const monthSwitch=()=>`<div class="month-switcher">${ib('chevron-left','Previous month',act('month','data-delta="-1"'))}<strong>${monthName(state.month)}</strong>${ib('chevron-right','Next month',act('month','data-delta="1"'))}</div>`;
const progress=(spent,limit)=>`<div class="progress-track" role="meter" aria-label="Budget used" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,Math.round(spent/Math.max(1,limit)*100))}"><div class="progress-fill ${spent>limit?'over':''}" style="width:${Math.min(100,spent/Math.max(1,limit)*100)}%"></div></div>`;
function balance(){let remaining=budget()-total();return `<div class="balance-card"><div class="balance-liquid aurora"></div><div class="balance-content"><div class="balance-top"><span class="double-circle"></span><span class="balance-period">${monthName(state.month)}</span></div><div class="balance-amount">${data.preferences.hideAmounts?'••••••':money(Math.abs(remaining))}</div><div class="balance-label">${remaining>=0?'Left to spend':'Over your budget'}</div></div><div class="balance-bottom"><div><strong>Your month, in balance.</strong><span>${data.preferences.hideAmounts?'••••':money(total(),0)} of ${data.preferences.hideAmounts?'••••':money(budget(),0)} spent</span></div><button class="balance-eye ${data.preferences.hideAmounts?'off':''}" ${act('hide-amounts')} aria-label="${data.preferences.hideAmounts?'Show':'Hide'} balances" aria-pressed="${data.preferences.hideAmounts}"></button></div></div>`}
function txRow(t){let c=cat(t.category);return `<button class="list-row" ${goAttr('expense',`data-tx="${esc(t.id)}"`)}><span class="merchant-icon ${c.id}">${I(c.icon)}</span><span class="row-main"><strong>${esc(t.merchant)}</strong><small>${c.name} · ${dateLabel(t.date)}</small></span><span class="row-end"><strong>−${money(t.cents)}</strong><small>${esc(t.payment)}</small></span></button>`}
function subMark(s,large=false){return `<span class="merchant-icon ${esc(s.brand||'subscriptions')} ${large?'sub-detail-icon':''}">${s.mark==='cloud'?I('cloud'):esc(s.mark||s.name.charAt(0).toUpperCase())}</span>`}
function subRow(s){return `<button class="list-row" ${goAttr('subscription',`data-sub="${esc(s.id)}"`)}>${subMark(s)}<span class="row-main"><strong>${esc(s.name)}</strong><small>${s.status==='active'?'Renews '+dateLabel(s.next):s.status==='paused'?'Tracking paused':'Marked cancelled'}</small></span><span class="row-end"><strong>${money(s.cents)}</strong><small>per ${s.cycle==='annual'?'year':'month'}</small></span></button>`}
function budgetRow(c){const spent=byCategory(c.id),limit=data.budget[c.id],remaining=limit-spent;return `<button class="category-budget" ${goAttr('category',`data-category="${c.id}"`)}><header><span class="merchant-icon ${c.id}">${I(c.icon)}</span><strong>${c.name}</strong>${I('chevron-right')}</header><div class="budget-values ${remaining<0?'over':''}"><span><b>${money(spent)}</b> / ${money(limit,0)}</span><span>${Math.round(spent/Math.max(limit,1)*100)}%</span></div>${progress(spent,limit)}<span class="budget-status ${remaining<0?'warning':''}">${money(Math.abs(remaining))} ${remaining<0?'over budget':'remaining'}</span></button>`}
function empty(title,copy,button='',to='add'){return `<div class="empty-state">${I('circle-dashed')}<h2>${title}</h2><p>${copy}</p>${button?pbtn(button,goAttr(to)):''}</div>`}
function pace(){const diff=forecast()-budget();return `<div class="pace-note ${diff<=0?'good':''}">${I(diff>0?'triangle-alert':'circle-check')}<span>${diff>0?`At this pace, you may finish ${money(diff)} over budget.`:`Your current pace is within your monthly budget.`}</span></div>`}
function chart(){let ds=daysIn(state.month),used=elapsed(),limit=budget(),tx=list(),max=Math.max(total(),limit)*1.12||100,x=d=>14+(d-1)/(ds-1)*288,y=v=>154-v/max*136;let vals=Array.from({length:used},(_,i)=>tx.filter(t=>Number(t.date.slice(8))<=i+1).reduce((s,t)=>s+t.cents,0)),path=vals.map((v,i)=>(i?'L':'M')+x(i+1).toFixed(1)+' '+y(v).toFixed(1)).join(' ');return `<svg viewBox="0 0 320 189" class="chart-svg" role="img" aria-label="Cumulative spending ${money(total())}, compared with a monthly budget of ${money(limit)}"><defs><linearGradient id="chartFade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b7f12b" stop-opacity=".2"/><stop offset="1" stop-color="#b7f12b" stop-opacity="0"/></linearGradient></defs>${[1,2,3].map(i=>`<path class="chart-grid" d="M14 ${154-i*40}H302"/>`).join('')}<path d="M14 154L302 ${y(limit).toFixed(1)}" stroke="#698253" stroke-width="1.5" stroke-dasharray="4 5" fill="none"/><path d="${path}L${x(used)} 154L14 154Z" fill="url(#chartFade)"/><path d="${path}" stroke="#b7f12b" stroke-width="2.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${x(used)}" cy="${y(total())}" r="4" fill="#b7f12b" stroke="#0b1207" stroke-width="2"/><text x="14" y="178">01</text><text x="104" y="178">10</text><text x="204" y="178">20</text><text x="290" y="178">${ds}</text></svg><div class="chart-legend"><span><b></b>Actual spending</span><span><b></b>Budget pace</span></div>`}
function donut(){let sum=total(),offset=0,circ=2*Math.PI*84;return `<div class="donut-wrap"><svg viewBox="0 0 210 210" role="img" aria-label="Spending distribution by category"><circle cx="105" cy="105" r="84" fill="none" stroke="#293b1d" stroke-width="17"/>${CAT.map(c=>{let val=byCategory(c.id),len=sum?val/sum*circ:0,str=`<circle cx="105" cy="105" r="84" fill="none" stroke="${c.color}" stroke-width="17" stroke-dasharray="${Math.max(0,len-4)} ${circ-Math.max(0,len-4)}" stroke-dashoffset="${-offset}"/>`;offset+=len;return val?str:''}).join('')}</svg><div class="donut-center"><strong>${money(sum,0)}</strong><small>Total spending</small></div></div>${CAT.map(c=>`<div class="legend-row"><b style="background:${c.color}"></b><span>${c.name}</span><strong>${money(byCategory(c.id))}</strong><small>${sum?Math.round(byCategory(c.id)/sum*100):0}%</small></div>`).join('')}`}
const toggle=(name,key,copy='')=>`<label class="toggle-row"><span>${name}${copy?`<small>${copy}</small>`:''}</span><input class="switch" type="checkbox" data-preference="${key}" aria-label="${name}" ${data.preferences[key]?'checked':''}></label>`;
const searchInput=(placeholder='Search expenses',value=state.query)=>`<label class="search-field">${I('search')}<input data-search aria-label="${placeholder}" value="${esc(value)}" placeholder="${placeholder}">${value?`<button ${act('clear-query')} aria-label="Clear search">${I('x')}</button>`:''}</label>`;
const optionCats=current=>CAT.map(c=>`<option value="${c.id}" ${c.id===current?'selected':''}>${c.name}</option>`).join('');
function renderScreen(id,preview=false){let body='',bottom='';
if(id==='welcome'){body=sc(`<div class="welcome-brand"><span class="luma-mark"><b></b><b></b></span> LUMA</div><h1>A little clarity.<br><em>A lot more calm.</em></h1><div class="welcome-liquid aurora"><span class="double-circle"></span><div class="sample-amount">${money(budget()-total())}<small>Room for the rest of your month</small></div><span class="micro-status">${I('sparkles')}Money, in focus.</span></div><p>See where your money goes.<br>Stay ahead of budgets and subscriptions.</p>${pbtn(`Find your balance ${I('arrow-right')}`,goAttr('overview'))}<div style="text-align:center">${link('How Luma works',act('how'),'')}</div>`,'welcome-scroll no-nav')}
if(id==='overview'){body=sc(`<div class="greeting"><div><p>Good morning, Alex</p><h1>A clearer view.</h1></div><div style="display:flex;gap:8px">${ib('bell','Open alerts',goAttr('alerts'),'transparent')}${ib('sliders-horizontal','Open settings',goAttr('settings'),'transparent')}</div></div>${balance()}<div class="quick-actions"><button ${goAttr('add')}>${I('plus')}Add expense</button><button ${goAttr('insights')}>${I('chart-no-axes-combined')}Insights</button><button ${goAttr('calendar')}>${I('calendar-days')}Renewals</button></div><div class="budget-glance"><div class="mini-stat"><small>Daily room · ${daysIn(state.month)-elapsed()} days left</small><strong>${money(Math.max(0,budget()-total())/Math.max(1,daysIn(state.month)-elapsed()))}</strong></div><div class="mini-stat"><small>Projected month-end</small><strong class="${forecast()>budget()?'warning':''}">${money(forecast(),0)}</strong></div></div><button class="feature-button" ${goAttr('budgets')}>${pace()}</button>${section('Recent activity','See all','transactions')}${list().slice(0,4).map(txRow).join('')}${section('Your recurring world','View all','subscriptions')}<div class="info-pairs"><span>${activeSubs().length} active subscriptions</span><strong>${money(monthlySubs())}/mo</strong></div>`);bottom=nav('overview')}
if(id==='transactions'){let filtered=list().filter(t=>state.filter==='all'||t.category===state.filter);body=sc(`<div class="greeting"><div><span class="app-eyebrow">Everyday spending</span><h1 style="margin-top:9px">Your activity.</h1></div>${ib('search','Search expenses',goAttr('search'),'transparent')}</div>${monthSwitch()}<div class="spent-summary"><div><span class="amount-label">Total spent</span><div class="amount-hero">${money(total())}</div></div><span class="badge">${list().length} expenses</span></div><div class="chips">${[['all','All'],...CAT.map(c=>[c.id,c.name])].map(([v,l])=>chip(l,state.filter===v,act('filter',`data-value="${v}"`))).join('')}</div>${filtered.length?filtered.map((t,i)=>`${i===0||filtered[i-1].date!==t.date?`<div class="list-divider-label">${dateLabel(t.date,{weekday:'short',month:'short',day:'numeric'})}</div>`:''}${txRow(t)}`).join(''):empty('A clean slate.','No expenses match this view.','Add an expense')}`);bottom=nav('transactions')}
if(id==='expense'){const t=currentTx();body=t?sc(`${top('Expense details','transactions',ib('trash-2','Delete expense',act('delete-expense'),'transparent'))}<div class="center"><span class="merchant-icon ${t.category} sub-detail-icon">${I(cat(t.category).icon)}</span><h2>${esc(t.merchant)}</h2><div class="detail-price">−${money(t.cents)}</div>${badge('Expense recorded')}</div><div class="detail-lines"><div class="detail-line"><span>Date</span><strong>${dateLabel(t.date,{month:'long',day:'numeric',year:'numeric'})}</strong></div><div class="detail-line"><span>Payment method</span><strong>${esc(t.payment)}</strong></div><div class="detail-line"><span>Category</span><strong>${cat(t.category).name}</strong></div></div><label class="form-field"><span>Move to a different category</span><select data-recategorize aria-label="Expense category">${optionCats(t.category)}</select></label><div class="receipt-note">${I('notebook-pen')}<div style="margin-top:10px">${esc(t.note||'No note added for this expense.')}</div></div><p class="financial-caption">Changes update your monthly totals and category budgets instantly.</p>`,'no-nav'):sc(`${top('Expense details','transactions')}${empty('Expense removed.','Your totals are up to date.','Back to activity','transactions')}`,'no-nav')}
if(id==='add'){body=sc(`${top('New expense','overview')}<span class="app-eyebrow">A moment to check in</span><h1>What did you spend?</h1><form data-form="expense" novalidate><div class="amount-input"><span>$</span><input name="amount" type="number" min="0.01" step="0.01" placeholder="0.00" aria-label="Expense amount" inputmode="decimal"></div><span class="form-label-text">Category</span><div class="category-pick">${CAT.map(c=>`<button type="button" class="${state.formCategory===c.id?'selected':''}" ${act('form-category',`data-value="${c.id}"`)} aria-pressed="${state.formCategory===c.id}">${I(c.icon)}${c.name}</button>`).join('')}</div><label class="form-field"><span>Merchant or description</span><input name="merchant" placeholder="e.g. Coffee at Morrow" maxlength="70" required></label><div class="form-grid"><label class="form-field"><span>Date</span><input name="date" type="date" value="2026-09-26" required></label><label class="form-field"><span>Paid with</span><select name="payment"><option>Debit card</option><option>Credit card</option><option>Cash</option></select></label></div><label class="form-field"><span>Note <small style="color:#728961">(optional)</small></span><input name="note" placeholder="A little context" maxlength="140"></label><div class="form-error" role="alert" ${state.error?'':'hidden'}>${esc(state.error)}</div>${pbtn('Save expense '+I('check'),'type="submit"')}<p class="tiny-note">Saved only on this device. No bank connection required.</p></form>`,'no-nav')}
if(id==='budgets'){body=sc(`<div class="greeting"><div><span class="app-eyebrow">Spend with intention</span><h1 style="margin-top:8px">Your monthly plan.</h1></div>${ib('sliders-horizontal','Edit budgets',goAttr('budget-edit'),'transparent')}</div>${monthSwitch()}<div class="spent-summary"><div><span class="amount-label">Monthly budget</span><div class="amount-hero">${money(budget(),0)}</div></div><span class="pill-badge ${total()>budget()?'warn':''}">${Math.round(total()/Math.max(budget(),1)*100)}% used</span></div>${progress(total(),budget())}<p style="font-size:12px;margin:11px 0 25px">${money(total())} spent · ${money(Math.abs(budget()-total()))} ${total()>budget()?'over budget':'left'}</p>${pace()}${section('By category','Edit','budget-edit')}${CAT.map(budgetRow).join('')}`);bottom=nav('budgets')}
if(id==='category'){const c=cat(state.category),spent=byCategory(c.id),limit=data.budget[c.id],tx=list().filter(t=>t.category===c.id);body=sc(`${top('Category budget','budgets',ib('pencil','Edit category budget',goAttr('budget-edit'),'transparent'))}<span class="merchant-icon ${c.id}" style="width:52px;height:52px;margin:10px 0 18px">${I(c.icon)}</span><h1>${c.name}</h1><div class="amount-label">Spent this month</div><div class="amount-hero">${money(spent)}</div><p style="font-size:13px">of ${money(limit,0)} budgeted</p>${progress(spent,limit)}<div class="pace-note ${spent<=limit?'good':''}" style="margin-top:22px">${I(spent>limit?'triangle-alert':'circle-check')}<span>${spent>limit?`${money(spent-limit)} over your plan. Review recent purchases or adjust the limit.`:`${money(limit-spent)} left in this category.`}</span></div>${section('The details')}<div class="list-total">${tx.length} expenses · ${monthName(state.month)}</div>${tx.length?tx.map(txRow).join(''):empty('Nothing here yet.','Expenses in this category will appear here.')}`);bottom=nav('budgets')}
if(id==='budget-edit'){body=sc(`${top('Monthly budget','budgets')}<h1>A plan that fits you.</h1><p style="font-size:13px">Choose a monthly limit for each category. You can adjust it whenever life changes.</p><form data-form="budget" novalidate><div class="subscription-hero"><span class="amount-label">Your total monthly budget</span><div class="amount-hero" data-budget-total>${money(budget(),0)}</div></div>${CAT.map(c=>`<div class="budget-editor"><label for="budget-${c.id}">${I(c.icon)}${c.name}</label><input id="budget-${c.id}" type="number" min="0" step="1" name="${c.id}" data-budget-input value="${data.budget[c.id]/100}" aria-label="${c.name} monthly budget"></div>`).join('')}<div class="form-error" role="alert" ${state.error?'':'hidden'}>${esc(state.error)}</div>${pbtn('Save my budget','type="submit" style="margin-top:27px"')}<p class="tiny-note">Limits apply across the demo’s monthly views.</p></form>`,'no-nav')}
if(id==='insights'){body=sc(`${top('Insights','overview',ib('file-chart-column','Monthly summary',goAttr('summary'),'transparent'))}<h1>Patterns, in focus.</h1>${monthSwitch()}<div class="segmented">${['Spending','Categories'].map(v=>`<button class="${state.insightTab===v?'active':''}" ${act('insight-tab',`data-value="${v}"`)}>${v}</button>`).join('')}</div>${state.insightTab==='Spending'?`<div class="amount-label">Total spending</div><div class="amount-hero">${money(total())}</div><div class="chart-panel"><h3>Your spending pace</h3><div class="chart-caption">Cumulative spend · ${elapsed()} days recorded</div>${chart()}</div><div class="summary-grid"><div class="summary-box"><span>Daily average</span><strong>${money(total()/elapsed())}</strong><small>Across this month so far</small></div><div class="summary-box"><span>Month-end estimate</span><strong>${money(forecast(),0)}</strong><small>At your current daily pace</small></div></div>${pace()}<p class="financial-caption">Projection = spending to date ÷ days elapsed × days in month. It is an estimate, not a scheduled-payment forecast.</p>`:`${donut()}<p class="financial-caption">Category shares use recorded expenses for the selected month. Subscription commitments are shown separately.</p>`}`);bottom=nav('overview')}
if(id==='subscriptions'){let subs=data.subscriptions.filter(s=>s.status===state.subFilter);body=sc(`<div class="greeting"><div><span class="app-eyebrow">Your recurring world</span><h1 style="margin-top:9px">Small charges.<br>Clear picture.</h1></div>${ib('plus','Add subscription',goAttr('subscription-add'),'lime')}</div><div class="subscription-hero"><div class="amount-label">Monthly commitment</div><div class="amount-hero">${money(monthlySubs())}<small>/mo</small></div><footer><span>${activeSubs().length} active services</span><span>${money(annualSubs(),0)} per year</span></footer></div><div class="action-bar-inline"><h2 style="font-size:18px">Your subscriptions</h2>${link('Calendar',goAttr('calendar'),'calendar-days')}</div><div class="chips">${['active','paused','cancelled'].map(v=>chip(v[0].toUpperCase()+v.slice(1),state.subFilter===v,act('sub-filter',`data-value="${v}"`))).join('')}</div>${subs.length?subs.sort((a,b)=>a.next.localeCompare(b.next)).map(subRow).join(''):empty(`No ${state.subFilter} subscriptions.`,state.subFilter==='active'?'Add your first service to track what renews.':'Manage a service to change its tracking status.',state.subFilter==='active'?'Add a subscription':'', 'subscription-add')}<p class="financial-caption">Annual plans are divided by 12 for the monthly equivalent. Subscription records do not automatically create expenses.</p>`);bottom=nav('subscriptions')}
if(id==='subscription'){const s=currentSub();body=s?sc(`${top('Subscription','subscriptions')}<div class="center">${subMark(s,true)}<h1 style="margin:0 0 11px">${esc(s.name)}</h1>${badge(s.status==='active'?'Active':s.status==='paused'?'Paused':'Cancelled',s.status==='active'?'':'neutral')}<div class="detail-price">${money(s.cents)}<small> / ${s.cycle==='annual'?'year':'month'}</small></div><p style="font-size:12px">${money(s.cycle==='annual'?s.cents/12:s.cents)} monthly equivalent</p></div><div class="detail-lines"><div class="detail-line"><span>Next renewal</span><strong>${dateLabel(s.next,{month:'long',day:'numeric',year:'numeric'})}</strong></div><div class="detail-line"><span>Billing cycle</span><strong>${s.cycle==='annual'?'Annual':'Monthly'}</strong></div><div class="detail-line"><span>Annual commitment</span><strong>${money(s.cycle==='annual'?s.cents:s.cents*12)}</strong></div></div><label class="toggle-row"><span>Renewal reminder<small>A heads-up before the next charge</small></span><input class="switch" type="checkbox" data-sub-reminder ${s.remind?'checked':''}></label><div class="detail-actions"><button class="secondary-button" ${act('pause-sub')}>${I(s.status==='active'?'pause':'play')}${s.status==='active'?'Pause tracking':'Resume tracking'}</button><button class="secondary-button" ${goAttr('calendar')}>${I('calendar-days')}See renewals</button></div>${s.status!=='cancelled'?`<button class="danger-button" ${act('cancel-sub')}>Mark as cancelled</button>`:''}<p class="privacy-copy">Tracking controls affect only Luma. To pause billing or cancel the actual service, contact the provider.</p>`,'no-nav'):sc(`${top('Subscription','subscriptions')}${empty('No service selected.','Add a subscription to get started.','Add subscription','subscription-add')}`,'no-nav')}
if(id==='subscription-add'){body=sc(`${top('New subscription','subscriptions')}<h1>Stay ahead<br>of the next charge.</h1><form data-form="subscription" novalidate><label class="form-field"><span>Service name</span><input name="name" placeholder="e.g. Figma, YouTube Premium" maxlength="50" required></label><div class="form-grid"><label class="form-field"><span>Amount ($)</span><input name="amount" type="number" step="0.01" min="0.01" placeholder="0.00" inputmode="decimal" required></label><label class="form-field"><span>Billing cycle</span><select name="cycle"><option value="monthly">Monthly</option><option value="annual">Annual</option></select></label></div><label class="form-field"><span>Next renewal</span><input name="next" type="date" value="2026-10-01" required></label><label class="toggle-row"><span>Remind me before renewal<small>Save a reminder preference</small></span><input class="switch" type="checkbox" name="remind" checked></label><div class="notice">${I('info')}Add the service once. Luma will show its monthly equivalent and upcoming renewal date.</div><div class="form-error" role="alert" ${state.error?'':'hidden'}>${esc(state.error)}</div>${pbtn('Add subscription '+I('plus'),'type="submit"')}<p class="tiny-note">No account credentials or payment details needed.</p></form>`,'no-nav')}
if(id==='calendar'){const [yr,mo]=state.calendarMonth.split('-').map(Number),first=new Date(yr,mo-1,1).getDay(),days=daysIn(state.calendarMonth),upcoming=activeSubs().filter(s=>s.next.startsWith(state.calendarMonth)),selected=upcoming.filter(s=>Number(s.next.slice(8))===state.calendarDay);body=sc(`${top('Renewals','subscriptions')}<h1>No surprises.</h1><div class="month-switcher">${ib('chevron-left','Previous renewal month',act('calendar-month','data-delta="-1"'))}<strong>${monthName(state.calendarMonth)}</strong>${ib('chevron-right','Next renewal month',act('calendar-month','data-delta="1"'))}</div><div class="calendar-grid">${['S','M','T','W','T','F','S'].map((d,i)=>`<span class="weekday" aria-label="${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][i]}">${d}</span>`).join('')}${Array.from({length:first},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{const day=i+1,count=upcoming.filter(s=>Number(s.next.slice(8))===day).length;return `<button class="calendar-day ${state.calendarDay===day?'selected':''}" ${act('calendar-day',`data-day="${day}"`)} aria-label="${monthName(state.calendarMonth)} ${day}, ${count} renewals" aria-pressed="${state.calendarDay===day}">${day}${count?'<span class="renewal-dot"></span>':''}</button>`}).join('')}</div><div class="info-pairs"><span>${upcoming.length} scheduled charges</span><strong>${money(upcoming.reduce((s,x)=>s+x.cents,0))}</strong></div>${section(dateLabel(state.calendarMonth+'-'+String(state.calendarDay).padStart(2,'0'),{month:'long',day:'numeric'}))}${selected.length?selected.map(subRow).join(''):`<div class="notice">${I('calendar-check-2')}No subscription renewals on this day.</div>`}${section('Coming this month')}${upcoming.map(subRow).join('')}`);bottom=nav('subscriptions')}
if(id==='alerts'){const over=CAT.filter(c=>byCategory(c.id)>data.budget[c.id]);body=sc(`${top('Notifications','overview')}<h1>A timely heads-up.</h1><div class="segmented">${['Updates','Preferences'].map(v=>`<button class="${state.alertTab===v?'active':''}" ${act('alert-tab',`data-value="${v}"`)}>${v}</button>`).join('')}</div>${state.alertTab==='Preferences'?`${toggle('Budget alerts','overspend','When spending goes beyond your plan.')}${toggle('Renewal reminders','renewals','A heads-up for upcoming subscriptions.')}${toggle('Weekly overview','weekly','A short recap of your spending week.')}<p class="privacy-copy">Preferences are saved locally. This concept does not send push notifications.</p>`:`${forecast()>budget()?`<div class="alert-entry warning"><div class="merchant-icon">${I('trending-up')}</div><div><h3>Your spending pace is running high.</h3><p>You could finish ${money(forecast()-budget())} above your ${money(budget(),0)} monthly budget.</p><time>Based on ${elapsed()} days of spending</time>${link('Review budget',goAttr('budgets'),'chevron-right')}</div></div>`:`<div class="alert-entry"><div class="merchant-icon">${I('circle-check')}</div><div><h3>Your plan is on track.</h3><p>Your current spending pace is within your budget.</p></div></div>`}${over.map(c=>`<div class="alert-entry warning"><div class="merchant-icon">${I(c.icon)}</div><div><h3>${c.name} is over budget.</h3><p>${money(byCategory(c.id)-data.budget[c.id])} above the ${money(data.budget[c.id],0)} category limit.</p>${link('See category',goAttr('category',`data-category="${c.id}"`),'chevron-right')}</div></div>`).join('')}${activeSubs().slice(0,1).map(s=>`<div class="alert-entry"><div class="merchant-icon">${I('repeat-2')}</div><div><h3>${esc(s.name)} renews ${dateLabel(s.next)}.</h3><p>${money(s.cents)} is scheduled for your next billing date.</p>${link('Manage subscription',goAttr('subscription',`data-sub="${s.id}"`),'chevron-right')}</div></div>`).join('')}`}`);bottom=nav('overview')}
if(id==='search'){const q=state.query.toLowerCase().trim(),matches=list().filter(t=>[t.merchant,cat(t.category).name,t.note].some(v=>String(v).toLowerCase().includes(q)));body=sc(`${top('Search','transactions')}<h1>Find that purchase.</h1>${searchInput('Merchant, category, or note')}<div aria-live="polite">${q?matches.length?`<div class="list-total">${matches.length} results · ${money(matches.reduce((s,t)=>s+t.cents,0))} total</div>${matches.map(txRow).join('')}`:empty('Nothing found.','Try another merchant name or a category, like “food”.'): `<div class="app-eyebrow" style="margin:28px 0 15px">Try a quick search</div><div class="chips">${['Coffee','Subscriptions','Home'].map(v=>chip(v,false,act('query',`data-value="${v}"`))).join('')}</div>${section('Recent activity')}${list().slice(0,4).map(txRow).join('')}`}</div>`);bottom=nav('transactions')}
if(id==='settings'){const row=(sym,label,target,extra='')=>`<button class="settings-row" ${target?goAttr(target):act('setting',`data-value="${label}"`)}>${I(sym)}<span class="setting-name">${label}</span>${extra?`<span class="setting-value">${extra}</span>`:''}${I('chevron-right')}</button>`;body=sc(`${top('Your preferences','overview')}<h1>Make it yours.</h1><div class="account-mark"><div class="avatar" style="width:48px;height:48px">AL</div><div><h3>Alex’s space</h3><p class="profile-note">Personal budget · USD</p></div></div><div class="settings-group"><small>Your money</small>${row('chart-no-axes-combined','Monthly budgets','budget-edit')}${row('repeat-2','Subscriptions','subscriptions')}${row('file-chart-column','Monthly summary','summary')}</div><div class="settings-group"><small>Preferences</small>${row('bell','Notifications','alerts')}${toggle('Hide balances','hideAmounts')}${toggle('Reduce motion','reduced')}</div><div class="settings-group"><small>About your data</small>${row('shield-check','Privacy & local storage')}${row('info','About Luma')}${row('rotate-ccw','Reset sample data')}</div><p class="privacy-copy">Demo snapshot: September 26, 2026. Your new entries stay in this browser and can be removed or reset.</p>`,'no-nav')}
if(id==='summary'){const sum=total(),limit=budget(),biggest=[...CAT].sort((a,b)=>byCategory(b.id)-byCategory(a.id))[0];body=sc(`${top('Monthly summary','insights')}<h1>The bigger picture.</h1>${monthSwitch()}<div class="month-report"><div class="report-heading"><span>SPENDING SUMMARY</span><span class="double-circle" style="transform:scale(.65);transform-origin:right"></span></div><div class="amount-hero">${money(sum)}</div><div class="amount-label">${state.month==='2026-09'?'Spent so far · September 26':'Total recorded spending'}</div><div class="report-footer"><span>${list().length} transactions</span><span>${Math.round(sum/Math.max(limit,1)*100)}% of budget</span></div></div><div class="summary-grid"><div class="summary-box"><span>${sum>limit?'Over budget':'Budget remaining'}</span><strong>${money(Math.abs(limit-sum),0)}</strong><small>Monthly limit ${money(limit,0)}</small></div><div class="summary-box"><span>Recurring commitment</span><strong>${money(monthlySubs())}</strong><small>${activeSubs().length} active services / month</small></div></div><div class="budget-outcome">${sum?`Your largest category was <strong>${biggest.name}</strong>, at ${money(byCategory(biggest.id))}.`:'No expenses have been recorded for this month.'}</div>${CAT.map(c=>`<div class="legend-row"><b style="background:${c.color}"></b><span>${c.name}</span><strong>${money(byCategory(c.id))}</strong></div>`).join('')}<div style="margin-top:25px">${pbtn('Review next month’s plan',goAttr('budget-edit'))}</div>`,'no-nav')}
return `${status()}${body}${bottom}<div class="home-indicator"></div>${!preview&&state.toast?`<div class="toast" role="status">${I('check')}${esc(state.toast)}</div>`:''}${!preview&&state.dialog?dialogHtml():''}`;
}
function dialogHtml(){let d=state.dialog;return `<div class="inline-dialog" role="dialog" aria-modal="true" aria-label="${esc(d.title)}"><div class="dialog-content"><div class="top-bar"><span class="app-eyebrow">Luma</span>${ib('x','Close dialog',act('close-dialog'),'transparent')}</div><h2>${esc(d.title)}</h2>${d.body}${pbtn(d.button||'Got it',act(d.action||'close-dialog'))}</div></div>`}
function phone(id,scale=1,live=false){return `<div class="phone-wrap" style="--scale:${scale}"><div class="phone"><div class="screen ${live&&state.hotspots?'hotspots':''}" ${live?'id="live-screen"':`aria-label="${esc(screens.find(s=>s[0]===id)?.[1])} preview"`}>${renderScreen(id,!live)}</div></div></div>`}
function presentation(){return `<section class="cover"><div class="cover-top"><div><div class="eyebrow">An expense tracker with a clearer perspective</div><h1>Your money.<br><em>Less mystery.</em></h1><div class="cover-meta"><span>17 CONNECTED SCREENS</span><span>ONE CALMER MONTH</span></div></div><div class="cover-right"><p class="intro">The everyday purchases.<br>The quiet subscriptions.<br>The bigger picture, finally in focus.</p><button class="cover-cta" data-launch="welcome">Enter the prototype ${I('arrow-up-right')}</button><p style="font-size:11px;color:#7d916b;margin-top:20px;line-height:1.7">A dark mobile finance concept.<br>Built around clarity, control, and a little glow.</p></div></div><div class="hero-phones">${phone('overview',.77)}${phone('subscriptions',.77)}${phone('budgets',.77)}</div></section><section class="section-document"><div class="section-top"><div><div class="eyebrow" style="color:var(--lime)">The experience</div><h2>Small check-ins.<br>A clearer month.</h2></div><p>A connected view of daily spending, monthly limits, and recurring payments. Enough context to notice a change and do something about it.</p></div><div class="flow-strip">${[['01','Check in','See what you’ve spent and what is left.'],['02','Track','Record a purchase in a few simple steps.'],['03','Understand','Find patterns in your monthly activity.'],['04','Plan','Set limits that fit your everyday life.'],['05','Stay ahead','Know which subscriptions renew next.'],['06','Adjust','Respond to a warning before month-end.']].map(([n,t,p])=>`<div><span>${n}</span><strong>${t}</strong><p>${p}</p></div>`).join('')}</div><div class="feature-spread"><div class="feature-copy"><div class="eyebrow">01 / A luminous point of focus</div><h3>See the number.<br>Understand the context.</h3><p>A bright, liquid-green balance sits against deep black. The rest of the interface stays restrained: thin numerical typography, quiet metadata, and useful signals when spending moves beyond the plan.</p><button class="text-link" data-launch="overview">Explore the monthly overview</button></div><div class="phone-stage">${phone('insights',.67)}${phone('category',.67)}</div></div><div class="feature-spread"><div class="phone-stage">${phone('subscriptions',.67)}${phone('calendar',.67)}</div><div class="feature-copy"><div class="eyebrow">02 / The quiet monthly commitments</div><h3>Recurring.<br>Never invisible.</h3><p>Understand the monthly equivalent of every service, see what renews next, and keep track of the subscriptions you have paused or cancelled.</p><button class="text-link" data-launch="subscriptions">Review recurring payments</button></div></div><div class="section-top" style="margin-top:85px;margin-bottom:0"><div><div class="eyebrow">The complete concept</div><h2>Every view.<br>One clear system.</h2></div><div><p>Browse the entire mobile experience, test the connected prototype, and inspect the color, type, spacing, and shape decisions extracted from the supplied reference.</p><button class="text-link" data-mode="gallery">View all 17 screens</button></div></div></section>`}
function gallery(){return `<div class="gallery-header"><div><div class="eyebrow">The complete mobile experience</div><h1>Seventeen views.<br>A clearer perspective.</h1><p>Open any screen in the prototype. Add expenses, change a budget, and explore recurring payments. Long screens scroll inside the live phone.</p><p class="print-note">Luma · Dark expense tracker concept · Sample financial data · The interactive companion contains the working prototype.</p></div><button class="text-link" data-launch="welcome">Play from the beginning</button></div><div class="gallery-grid">${screens.map(([id,label],i)=>`<article class="gallery-item"><div data-preview="${id}">${phone(id,.65)}</div><div class="gallery-label"><strong>${label}</strong><span>${String(i+1).padStart(2,'0')} / 17</span></div><button class="gallery-open" data-launch="${id}">Open prototype ${I('arrow-up-right')}</button></article>`).join('')}</div>`}
function prototype(){let s=screens.find(s=>s[0]===state.screen);return `<div class="prototype-layout"><aside class="screen-index"><h2>App screens</h2>${screens.map(([id,label],i)=>`<button data-launch="${id}" class="${id===state.screen?'current':''}"><span>${String(i+1).padStart(2,'0')}</span>${label}</button>`).join('')}</aside><section class="prototype-stage"><div class="prototype-controls"><button data-restart>${I('rotate-ccw')}Restart</button><button data-hotspots aria-pressed="${state.hotspots}">${I('scan')}Touch targets</button><select data-width aria-label="Preview phone width">${[375,390,393,430].map(w=>`<option value="${w}" ${state.width===w?'selected':''}>${w}px</option>`).join('')}</select></div>${phone(state.screen,.91,true)}<p class="prototype-caption">Tap, scroll, add an expense, or change a budget.<br>Your changes stay on this device.</p></section><aside class="prototype-notes"><div class="eyebrow">${String(screens.indexOf(s)+1).padStart(2,'0')} / 17 · ${s[1]}</div><h2>${s[2]}</h2><p>${s[3]}</p><ul>${s[4].map(t=>`<li>${t}</li>`).join('')}</ul><div class="journey"><div class="eyebrow">Suggested walkthrough</div><button data-launch="overview">1. Check the month’s balance</button><button data-launch="add">2. Add a purchase</button><button data-launch="budgets">3. Review a budget warning</button><button data-launch="subscriptions">4. Manage recurring payments</button><button data-launch="calendar">5. Check the next renewal</button></div><p style="font-size:11px;margin-top:25px">Sample snapshot: September 26, 2026. USD. All records are local; bank syncing, push delivery, and provider cancellations are outside this prototype.</p></aside></div>`}
function system(){return `<section class="section-document"><div class="section-top"><div><div class="eyebrow">Reference to design language</div><h2>Deep black.<br>A deliberate glow.</h2></div><p>The supplied image sets the visual direction: luminous green, generous black space, light numerical typography, soft corners, and an overlapping-circle motif.</p></div><section class="system-panel"><h3>The reference, translated.</h3><div class="reference-study"><img src="reference.png" alt="Supplied reference: black banking card with luminous green balance panel and overlapping circles"><div><div class="eyebrow" style="color:var(--lime)">Brand analysis</div><ul class="reference-list"><li>Near-black is the dominant product surface.</li><li>Lime, forest, and pale green form the luminous balance treatment.</li><li>Large amounts use a light weight and tight spacing.</li><li>Rounded outer shells contrast with an angled inner cutout.</li><li>Overlapping circles become Luma’s simple identifying mark.</li><li>Small controls repeat the green treatment with restraint.</li></ul><p>Typography and spacing are matched visually. A raster reference does not reveal its exact font family or original layout measurements.</p></div></div></section><div class="system-grid"><section class="system-panel"><h3>Color extracted from the reference</h3><div class="swatches">${[['Reference black','#000000'],['App canvas','#080A07'],['Raised surface','#141711'],['Lime action','#B7F12B'],['Reference green','#8DCA2A'],['Reference forest','#234D11'],['Reference pale','#C3E561'],['Reference backdrop','#D9DED8'],['Text','#F1F4E9']].map(([n,c])=>`<div><div class="swatch-color" style="background:${c}"></div><strong>${n}</strong><small>${c}</small></div>`).join('')}</div><div class="color-ribbon"></div><p class="system-copy">Sampled reference colors guide the palette. Accessible text and action tones extend it for a complete mobile interface. Lime means action or positive balance; amber identifies budget overruns.</p></section><section class="system-panel"><h3>Light numbers. Clear hierarchy.</h3>${[['Balance','$2,136.80',43,48,300],['Screen title','A clearer view.',29,34,500],['Section','Recent activity',18,24,500],['Body','Know what is coming.',15,22,400],['Metadata','Renews October 3',12,18,400]].map(([n,t,z,h,w])=>`<div class="type-sample"><span style="font-size:${z}px;line-height:${h}px;font-weight:${w};letter-spacing:${z>25?'-1px':'0'}">${t}</span><small>${n}<br>${z}/${h}</small></div>`).join('')}<p class="system-copy">Helvetica Neue, Segoe UI, then Arial. The device’s available font provides the closest system match. Financial values use tabular figures and retain two decimal places.</p></section><section class="system-panel"><h3>Shape and component language</h3><div class="component-examples">${pbtn('Save expense')}${ib('plus','Add expense','','lime')}<button class="secondary-button">View details</button>${chip('Active',true)}${badge('Over budget','warn')}</div><div class="state-demo"><h4>A meaningful selected state</h4><div class="component-examples">${chip('All',true)}${chip('Food & drink')}${badge('Tracking paused','neutral')}</div></div><p class="system-copy">A 30px balance panel, 16–20px content groups, circular icon controls, and pill actions echo the reference without making every row a card.</p></section><section class="system-panel"><h3>Spacing and motion</h3><div class="spec-list"><div><strong>20px</strong>Screen padding</div><div><strong>24–32px</strong>Section spacing</div><div><strong>44px</strong>Icon hit targets</div><div><strong>52px</strong>Primary actions</div><div><strong>150 / 280ms</strong>Press / navigation</div><div><strong>375–430px</strong>Responsive phone widths</div></div><p class="system-copy">Eight-pixel spacing with small optical adjustments. Subtle movement keeps changes legible. Reduced-motion preferences turn transitions off.</p></section><section class="system-panel"><h3>Useful feedback, without noise</h3><div class="pace-note">${I('triangle-alert')}<span>You could finish above your monthly budget.</span></div><div class="pace-note good" style="margin-top:12px">${I('circle-check')}<span>Your spending pace is within your plan.</span></div><div class="state-demo">${empty('Nothing found.','Try a merchant name or category.')}</div></section><section class="system-panel"><h3>One connected financial model</h3><p class="system-copy">Expenses are stored as integer cents. Monthly totals, remaining budget, category usage, and projections are calculated from the same records. Annual subscription fees are normalized into monthly equivalents.</p><p class="system-copy">The demo uses September 26, 2026 as its snapshot. Data stays in local browser storage. Subscription tracking does not cancel services or automatically post charges. Projections are simple pace estimates, not financial advice.</p><button class="text-link" data-launch="overview">Try the live calculations</button></section></div></section>`}
function render(){let root=$('#document');root.innerHTML=state.mode==='presentation'?presentation():state.mode==='gallery'?gallery():state.mode==='prototype'?prototype():system();document.querySelectorAll('.document-nav [data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===state.mode));icons();applyWidth()}
function applyWidth(){document.body.classList.toggle('force-reduced-motion',!!data.preferences.reduced);if(state.mode!=='prototype')return;let screen=$('#live-screen'),p=screen?.closest('.phone'),wrap=p?.parentElement;if(!screen)return;let width=state.width+16,scale=Math.min(.91,(innerWidth-24)/width);wrap.style.width=width*scale+'px';wrap.style.height=860*scale+'px';wrap.style.setProperty('--scale',scale);p.style.width=width+'px';screen.style.width=state.width+'px'}
function update(keep=true,focus=false){const screen=$('#live-screen');if(!screen)return render();const old=screen.querySelector('.phone-scroll')?.scrollTop||0,selection=document.activeElement?.selectionStart;screen.innerHTML=renderScreen(state.screen);icons();if(keep&&screen.querySelector('.phone-scroll'))screen.querySelector('.phone-scroll').scrollTop=old;if(focus){let inp=screen.querySelector('[data-search]');inp?.focus();if(inp&&selection!=null)inp.setSelectionRange(selection,selection)}applyWidth()}
function go(screen,options={}){if(!screens.some(s=>s[0]===screen))return;Object.assign(state,options);state.screen=screen;state.mode='prototype';state.dialog=null;state.error='';state.toast='';render();$('#live-screen .phone-scroll')?.classList.add('screen-enter')}
function mode(value){state.mode=value;state.dialog=null;render();window.scrollTo({top:0,behavior:'instant'})}
let toastTimer;function toast(message){state.toast=message;update();clearTimeout(toastTimer);toastTimer=setTimeout(()=>{state.toast='';$('#live-screen .toast')?.remove()},2500)}
function dialog(title,body,button='Got it',action='close-dialog'){state.dialog={title,body,button,action};update();$('#live-screen .dialog-content button')?.focus()}
function shiftMonth(value,delta){let d=new Date(value+'-01T12:00:00');d.setMonth(d.getMonth()+delta);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')}
function execute(name,el){const v=el.dataset.value;
if(name==='how')return dialog('A little clarity, every day.',`<p>Record everyday expenses. Set category budgets. Keep an eye on recurring subscriptions and upcoming renewals.</p><div class="notice">${I('shield-check')}This is a device-local prototype using sample records. No accounts are connected.</div>`,'Find my balance','begin');
if(name==='begin')return go('overview');if(name==='close-dialog'){state.dialog=null;return update()}
if(name==='hide-amounts'){data.preferences.hideAmounts=!data.preferences.hideAmounts;persist();return update()}
if(name==='month'){state.month=shiftMonth(state.month,Number(el.dataset.delta));return update(false)}
if(name==='filter'){state.filter=v;return update(false)}
if(name==='insight-tab'){state.insightTab=v;return update(false)}
if(name==='sub-filter'){state.subFilter=v;return update(false)}
if(name==='alert-tab'){state.alertTab=v;return update(false)}
if(name==='query'){state.query=v;return update(true,true)}
if(name==='clear-query'){state.query='';return update(true,true)}
if(name==='form-category'){state.formCategory=v;document.querySelectorAll('#live-screen [data-action="form-category"]').forEach(b=>{b.classList.toggle('selected',b.dataset.value===v);b.setAttribute('aria-pressed',b.dataset.value===v)});return}
if(name==='calendar-month'){state.calendarMonth=shiftMonth(state.calendarMonth,Number(el.dataset.delta));state.calendarDay=1;return update(false)}
if(name==='calendar-day'){state.calendarDay=Number(el.dataset.day);return update()}
if(name==='delete-expense')return dialog('Remove this expense?',`<p>${esc(currentTx()?.merchant)} · ${money(currentTx()?.cents||0)}</p><p style="margin-top:15px">It will be removed from this device’s records. Your monthly totals and category budget will update.</p>`,'Remove expense','confirm-delete');
if(name==='confirm-delete'){data.transactions=data.transactions.filter(t=>t.id!==state.tx);persist();go('transactions');return toast('Expense removed. Totals updated.')}
if(name==='pause-sub'){const s=currentSub();s.status=s.status==='active'?'paused':'active';persist();return toast(s.status==='active'?'Subscription tracking resumed':'Tracking paused. Provider billing is unchanged.')}
if(name==='cancel-sub')return dialog('Mark this service cancelled?',`<p>This updates your Luma records only. It does not cancel billing with ${esc(currentSub().name)}.</p><p style="margin-top:15px">Confirm after arranging cancellation directly with the provider.</p>`,'Mark as cancelled','confirm-cancel');
if(name==='confirm-cancel'){currentSub().status='cancelled';persist();state.dialog=null;return toast('Marked cancelled in your tracker')}
if(name==='setting'){if(v==='Reset sample data')return dialog('Start with a fresh month?',`<p>Your added expenses, subscription changes, and budget edits on this device will be replaced by the original sample data.</p>`,'Reset sample data','reset-data');if(v==='Privacy & local storage')return dialog('Your data stays here.','<p>This prototype stores your expenses, category budgets, subscriptions, and preferences only in this browser. No bank, payment processor, or analytics service is connected.</p><p style="margin-top:15px">You can delete individual records or reset the complete sample dataset.</p>');return dialog('A clearer view of your money.','<p>Luma is a mobile expense-tracking concept built around monthly spending, budgets, and recurring commitments.</p><p style="margin-top:15px">Its dark canvas, luminous lime panels, overlapping circles, and light numerical typography are drawn from the supplied visual reference.</p>')}
if(name==='reset-data'){Object.keys(data).forEach(k=>delete data[k]);Object.assign(data,structuredClone(defaults));persist();state.month='2026-09';state.filter='all';state.subFilter='active';state.tx='t24';state.sub='s0';go('overview');return toast('Sample data restored')}
}
function formError(form,message){state.error=message;const box=form.querySelector('.form-error');box.textContent=message;box.hidden=false;box.scrollIntoView({block:'nearest',behavior:'smooth'})}
const amountValid=n=>Number.isFinite(n)&&n>0&&n<=1000000;
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form||!form.closest('#live-screen'))return;e.preventDefault();const f=new FormData(form);if(form.dataset.form==='expense'){const amount=Number(f.get('amount')),merchant=String(f.get('merchant')||'').trim(),date=String(f.get('date')||'');if(!amountValid(amount))return formError(form,'Enter an amount greater than $0 and no more than $1,000,000.');if(!merchant)return formError(form,'Add a merchant or a short description.');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date)))return formError(form,'Choose a valid expense date.');const t={id:'t'+Date.now(),merchant,cents:Math.round(amount*100),category:state.formCategory,date,payment:String(f.get('payment')),note:String(f.get('note')||'').trim(),created:Date.now()};data.transactions.push(t);state.month=date.slice(0,7);state.tx=t.id;persist();go('overview');return toast('Expense saved. Your month is up to date.')}
if(form.dataset.form==='budget'){let values={};for(const c of CAT){const n=Number(f.get(c.id));if(!Number.isFinite(n)||n<0||n>1000000)return formError(form,'Category budgets must be between $0 and $1,000,000.');values[c.id]=Math.round(n*100)}if(Object.values(values).reduce((s,v)=>s+v,0)<=0)return formError(form,'Set at least one category budget above $0.');data.budget=values;persist();go('budgets');return toast('Monthly budget updated')}
if(form.dataset.form==='subscription'){const name=String(f.get('name')||'').trim(),amount=Number(f.get('amount')),next=String(f.get('next')||'');if(!name)return formError(form,'Enter the subscription or service name.');if(!amountValid(amount))return formError(form,'Enter a valid subscription amount above $0.');if(!/^\d{4}-\d{2}-\d{2}$/.test(next)||Number.isNaN(Date.parse(next)))return formError(form,'Choose a valid renewal date.');const s={id:'s'+Date.now(),name,cents:Math.round(amount*100),next,cycle:String(f.get('cycle')),brand:'subscriptions',mark:name[0].toUpperCase(),status:'active',remind:f.get('remind')==='on'};data.subscriptions.push(s);state.sub=s.id;state.subFilter='active';persist();go('subscriptions');toast('Subscription added to your recurring view')}
});
document.addEventListener('click',e=>{const l=e.target.closest('[data-launch]');if(l){go(l.dataset.launch);window.scrollTo({top:0,behavior:'instant'});return}const m=e.target.closest('[data-mode]');if(m)return mode(m.dataset.mode);const preview=e.target.closest('[data-preview]');if(preview){go(preview.dataset.preview);window.scrollTo({top:0,behavior:'instant'});return}if(e.target.closest('[data-restart]'))return go('welcome');if(e.target.closest('[data-hotspots]')){state.hotspots=!state.hotspots;return render()}if(!e.target.closest('#live-screen'))return;const dest=e.target.closest('[data-go]');if(dest){let opts={};for(const key of ['tx','sub','category'])if(dest.dataset[key])opts[key]=dest.dataset[key];return go(dest.dataset.go,opts)}const a=e.target.closest('[data-action]');if(a){e.preventDefault();execute(a.dataset.action,a)}});
document.addEventListener('input',e=>{if(!e.target.closest('#live-screen'))return;if(e.target.matches('[data-search]')){state.query=e.target.value;update(true,true)}if(e.target.matches('[data-budget-input]')){const vals=[...document.querySelectorAll('#live-screen [data-budget-input]')].map(x=>Number(x.value));$('#live-screen [data-budget-total]').textContent=money(vals.reduce((s,v)=>s+(Number.isFinite(v)?v*100:0),0),0)}});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-width]')){state.width=Number(el.value);return applyWidth()}if(!el.closest('#live-screen'))return;if(el.dataset.preference){data.preferences[el.dataset.preference]=el.checked;persist();applyWidth()}if(el.matches('[data-sub-reminder]')){currentSub().remind=el.checked;persist()}if(el.matches('[data-recategorize]')){currentTx().category=el.value;persist();toast('Category updated. Budgets recalculated.')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.dialog){state.dialog=null;update()}if(e.key==='Tab'&&state.dialog){const focusables=[...document.querySelectorAll('#live-screen .dialog-content button,#live-screen .dialog-content input')];const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
$('#print').addEventListener('click',()=>{mode('gallery');setTimeout(()=>window.print(),150)});window.addEventListener('resize',applyWidth);window.addEventListener('hashchange',()=>{if(location.hash==='#presentation')mode('presentation')});
const params=new URLSearchParams(location.search);if(params.get('screen')&&screens.some(s=>s[0]===params.get('screen'))){state.screen=params.get('screen');state.mode='prototype'}else if(['gallery','prototype','system'].includes(params.get('view')))state.mode=params.get('view');
window.lumaDemo={state,data,screens,go,mode,render,total,budget,forecast,monthlySubs,annualSubs,byCategory};render();
})();
